import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"60、【节】 兑下坎上","description":"周易口诀义 - 60、【节】 兑下坎上","frontmatter":{"title":"60、【节】 兑下坎上","description":"周易口诀义 - 60、【节】 兑下坎上"},"headers":[],"relativePath":"zh/classics/koujueyi/062.md","filePath":"zh/classics/koujueyi/062.md"}'),r={name:"zh/classics/koujueyi/062.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_60、【节】-兑下坎上" tabindex="-1">60、【节】 兑下坎上 <a class="header-anchor" href="#_60、【节】-兑下坎上" aria-label="Permalink to “60、【节】 兑下坎上”">​</a></h1><p>彖曰：「节亨」，刚柔分而刚得中。「苦节不可贞」，其道穷也。说以行险，当位以节，中正以通。天地节而四时成，节以制度，不伤财，不害民。</p><p>象曰：泽上有水，节。君子以制数度，议德行。</p><p>初九：不出户庭，无咎。</p><p>象曰：「不出户庭」，知通塞也。</p><p>九二：不出门庭，凶。</p><p>象曰：「不出门庭凶」，失时极也。</p><p>六三：不节若，则嗟若，无咎。</p><p>象曰：「不节」之「嗟」，又谁咎也。</p><p>六四：安节，亨。</p><p>象曰：「安节」之「亨」，承上道也。</p><p>九五，甘节，吉，往有尚。</p><p>象曰：「甘节」之「吉」，居位中也。</p><p>上六，苦节，贞凶，悔亡。</p><p>象曰「苦节贞凶」，其道穷也。</p><p>解读</p><p>「节，亨」者，节，制度之名，节止之义，故谓之「节」也。节制要在得宜，尊卑有别，其道乃通，故曰「节亨」也。「苦节，不可贞」者，为节之道，必须当理，若过刻薄，伤于物情，物所不堪，非为节道，不可为正，故「苦节不可贞」也。象曰「泽上有水，节」者，「泽」，陂陷之处也。泽之大小，各有区别，今水居节上，随其大小得宜，各有止节，故为节象也。「君子以制数度，议德行」者，「数」谓礼数等差也，「度」谓上下优劣也。议人德行，轻重得宜，是皆节制度数之义，所以周礼五等诸侯所受锡命，皆有度数是也。</p><p>「初九，不出户庭，无咎」者，节者，制度之义。今初九处节之初，即是初制法度，宜其慎密，不令泄露。若教令未宣而乃泄露，即人心多险，奸诈生焉。若慎密不失，施制合宜，应时无伪，乃得「无咎」，知通塞矣。</p><p>「九二，不出门庭，凶」者，初为制度之始，法制未成，固宜慎密。今至九二，是法制已成，而犹溺之，失时之中，乃乖于理，失时之极，所以致凶，故曰「不出门庭，凶」也。</p><p>「六三，不节若，则嗟若，无咎」者，处节之时，故宜各得其序，不相乖越。今六三以阴居阳，以柔乘刚，以为骄僭而不为节，祸将及身，以至哀嗟，故曰「不节若」也。祸自己招，非人所与，无所怨咎于人，故曰「无咎」。</p><p>「六四，安节，亨」者，以柔得位，承顺于君，是得节之道，但称安行此节而不改变，则何往不通？故曰「安节，亨」也。</p><p>「九五，甘节，吉，往有尚」者，不苦而美谓之甘也。九五为节之主，履正居中，节以制度，不伤财，不害人，为节而无伤，即是不苦而甘，所以甘吉矣；为节不伤，苦而能甘，以此而往，人所嘉尚，故曰「往有尚」也。</p><p>「上六，苦节，贞凶，悔亡」者，居节之极，是过节之中，伤于为正，物所不堪，正之凶矣，故曰「苦节贞凶」。若以施人，则是正道，凶；若以苦节于身，修己自厉，则可以「悔亡」矣。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
